"""交互操作页；所有图像和车辆位置均来自当前新运行。"""
HTML = r'''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>启动感知导航仿真</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f5f7;color:#19313e;font:15px/1.6 system-ui,sans-serif}main{max-width:1380px;margin:auto;padding:22px}h1{font-size:26px;margin:0}h2{font-size:17px;margin:0 0 10px}p{margin:8px 0}.muted{font-size:13px;color:#506775}.card{background:white;border:1px solid #d0dde4;border-radius:8px;padding:16px;min-width:0}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}button,select{font:inherit;border:1px solid #a9bdc9;border-radius:5px;padding:8px;background:white;max-width:100%}button{cursor:pointer}button:disabled{cursor:default;opacity:.48}button#start{background:#176880;color:white}button#stop{border-color:#a84635;color:#973323}select#task{flex:1;min-width:180px}label{white-space:nowrap}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.wide{grid-column:1/-1}img,canvas{display:block;width:100%;height:auto;aspect-ratio:16/9;background:#e9eff3}#plan{aspect-ratio:1200/430}.stats{display:flex;flex-wrap:wrap;gap:8px}.stat{padding:5px 10px;background:#eaf2f6;white-space:nowrap;border-radius:5px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:300px;overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #dce5ea;padding:5px;overflow-wrap:anywhere}#error{color:#9b301e;min-height:24px}a{color:#176880}.links{display:flex;gap:14px;flex-wrap:wrap}#session{overflow-wrap:anywhere}@media(max-width:800px){main{padding:12px}.grid{grid-template-columns:1fr}h1{font-size:22px}.card{padding:12px}select#task{flex-basis:100%}}
</style><main><h1>启动感知导航仿真</h1><p>选择冻结开发任务，实际运行车载感知、对象图、规划与车辆控制。</p>
<p class="muted">当前使用CPU真实YOLO／SAM／CLIP与软件渲染。仿真按固定0.1秒积分；计算耗时不代表实时性能。交互运行单独保存，不纳入冻结主表，新封存测试保持关闭。</p>
<div class="controls"><select id="task" aria-label="冻结开发任务"></select><label>种子 <select id="seed" aria-label="扰动种子"></select></label><button id="start">开始新运行</button></div>
<p id="query"></p><div class="controls"><button id="step" disabled>推进0.5仿真秒</button><button id="run" disabled>连续运行</button><button id="pause" disabled>暂停仿真</button><button id="stop" disabled>停车并结束</button><button id="refresh">刷新状态</button></div>
<p class="muted">暂停会冻结仿真时钟并保留当时速度；车辆是否刹停以零速状态为准。前端处理中的控制命令会排队，停车按制动限制逐步执行。每会话最多900秒墙钟、30秒仿真和80次前端。</p>
<p id="error" role="alert"></p><div class="stats" id="stats"><span class="stat">尚未启动</span></div><p id="session" class="muted"></p>
<div class="grid" style="margin-top:16px"><section class="card"><h2>当前重新渲染的RGB</h2><img id="rgb" alt="新运行当帧车载RGB"><p id="frame" class="muted">等待首次实际观测</p></section><section class="card"><h2>实际检测与SAM输出</h2><img id="detection" alt="当前真实前端输出"></section><section class="card"><h2>有效LiDAR显示副本</h2><img id="depth" alt="稀疏LiDAR的颜色显示"><p class="muted">仅对有效深度着色，显示范围0–60米；黑色为无深度。原16位深度另附链接。</p></section>
<section class="card wide"><h2>道路、估计对象、计划与实际执行</h2><canvas id="plan" width="1200" height="430"></canvas><p class="muted">世界坐标平面图，单位米。蓝灰道路、灰色当前实测障碍、橙色计划、绿色实际轨迹、红色矩形车身。图中不显示目标真值位置。</p></section>
<section class="card wide"><h2>四项独立结果</h2><div class="stats" id="outcomes"><span class="stat">运行尚未终止，最终结果未知</span></div><p class="muted">选对Top1和正确锁定是观测中曾发生的事件；实际到达另需正确身份、安全区域、航向、低速及2秒保持。</p><p id="termination"></p><div class="links" id="links"></div></section>
<section class="card wide"><h2>当前候选、对象图与控制依据</h2><div id="candidates"></div><details><summary>当前对象、关系、解析与计划</summary><pre id="details"></pre></details></section></div></main>
<script>
const $=id=>document.getElementById(id),pretty=v=>JSON.stringify(v,null,2);let tasks=[],state=null,busy=false,timer;
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),esc=v=>String(v??'unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});const v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v}
function query(){const t=tasks.find(v=>v.task_id===$('task').value);$('query').textContent=t?.query_text||''}
function draw(){const c=$('plan'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!state?.road_polygon_xy)return;const road=state.road_polygon_xy,xs=road.map(p=>p[0]),ys=road.map(p=>p[1]),xmin=Math.min(...xs)-4,ymin=Math.min(...ys)-5,xmax=Math.max(...xs)+4,ymax=Math.max(...ys)+5,sc=Math.min((c.width-70)/(xmax-xmin),(c.height-60)/(ymax-ymin)),cx=(xmin+xmax)/2,cy=(ymin+ymax)/2;
const point=p=>[c.width/2+(p[0]-cx)*sc,c.height/2-(p[1]-cy)*sc];function line(ps,color,width=1,fill=null){if(!ps?.length)return;ctx.beginPath();ps.forEach((p,i)=>{const q=point(p);i?ctx.lineTo(...q):ctx.moveTo(...q)});if(fill){ctx.closePath();ctx.fillStyle=fill;ctx.fill()}ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
line(road,'#7192a7',1,'#dfeaf0');line(state.centerline_xy,'#8ba1ad');for(const o of state.frame?.known_obstacle_polygons||[])line(o,'#7c8c96',1,'#c7d1d7');line(state.frame?.path_world,'#cb7b24',3);line(state.execution_xy,'#14735d',3);for(const n of state.frame?.nodes||[]){const [x,y]=n.center,[w,h]=n.extent;line([[x-w/2,y-h/2],[x+w/2,y-h/2],[x+w/2,y+h/2],[x-w/2,y+h/2],[x-w/2,y-h/2]],'#326a8b',1);const p=point(n.center);ctx.font='14px sans-serif';ctx.fillStyle='#224d68';ctx.fillText('节点'+n.node_id,p[0],p[1]-4)}
const s=state.state,v=state.vehicle_spec;if(s&&v){const body=[[-v.rear_overhang_m,-v.width_m/2],[v.front_from_rear_axle_m,-v.width_m/2],[v.front_from_rear_axle_m,v.width_m/2],[-v.rear_overhang_m,v.width_m/2],[-v.rear_overhang_m,-v.width_m/2]].map(([x,y])=>[s.x+Math.cos(s.yaw_rad)*x-Math.sin(s.yaw_rad)*y,s.y+Math.sin(s.yaw_rad)*x+Math.cos(s.yaw_rad)*y]);line(body,'#ae3b32',2,'#ae3b3230')}}
function render(){if(!state)return;const active=state.worker_alive&&!['FINISHED','FAILED','WORKER_EXITED_WITHOUT_RESULT'].includes(state.phase);$('start').disabled=!!state.worker_alive||busy;$('task').disabled=!!state.worker_alive;$('seed').disabled=!!state.worker_alive;for(const id of ['step','run','pause','stop'])$(id).disabled=!active||busy;
const s=state.state,phases={IDLE:'尚未启动',STARTING:'进程启动中',INITIALIZING:'加载CPU模型',PERCEIVING:'实际感知处理中',PAUSED:'仿真已暂停',READY:'控制推进中',FINISHED:'运行已终止',FAILED:'运行失败',WORKER_EXITED_WITHOUT_RESULT:'进程退出且缺完整结果'};
const entries=[phases[state.phase]||state.phase,state.mode?'模式 '+state.mode:null,s?'仿真 '+s.time_s.toFixed(1)+' 秒':null,s?'速度 '+s.speed_mps.toFixed(3)+' m/s':null,state.counts?'真实前端 '+state.counts.actual_frontend_calls+' 次':null];$('stats').innerHTML=entries.filter(Boolean).map(v=>'<span class="stat">'+esc(v)+'</span>').join('');$('session').textContent=state.run_id?'当前运行：'+state.run_id+'；实际worker '+(state.worker_alive?'存活':'已退出'):'';if(state.query_text)$('query').textContent=state.query_text;
const f=state.frame;if(f){for(const [id,url] of [['rgb',f.rgb_url],['detection',f.detection_url],['depth',f.depth_view_url]])if($(id).getAttribute('src')!==url)$(id).src=url;$('frame').textContent='实际观测 '+f.frame_idx+'；感知位姿仿真 '+f.sensor.state.time_s.toFixed(1)+' 秒；有效深度 '+f.sensor.lidar_pixels+' 像素';$('candidates').innerHTML='<table><tr><th>安全候选节点</th><th>保存评分</th></tr>'+f.candidates.map(n=>'<tr><td>'+esc(n.node_id)+'</td><td>'+n.score.toFixed(4)+'</td></tr>').join('')+'</table>';$('details').textContent=pretty({nodes:f.nodes,relations:f.relations,parsed_query:f.parsed_query,lock:f.lock,planning:f.planning});}
const r=state.result;$('outcomes').innerHTML=r?[['route_generated','生成路线'],['selected_object_evaluated_correct','曾选对Top1'],['stable_correct_lock','曾正确锁定'],['actual_full_perception_arrival','实际到达']].map(([k,n])=>'<span class="stat">'+n+'：'+(r[k]?'是':'否')+'</span>').join(''):'<span class="stat">运行尚未终止，最终结果未知</span>';$('termination').textContent=r?'终止状态 '+r.status+'；终点零速 '+(r.terminal_zero_speed?'是':'否')+'；执行审核 '+(r.independent_execution_audit.passed?'通过':'未通过'):'';const base=state.session_url;$('links').innerHTML=base?[['release.json','本次冻结与预算'],['commands.jsonl','操作命令'],['execution.jsonl','实际控制轨迹'],['perception.jsonl','实际感知日志'],...(r?[['result.json','独立结果']]:[])].map(([p,n])=>'<a target="_blank" href="'+base+p+'">'+n+'</a>').join('')+(f?'<a target="_blank" href="'+f.depth_url+'">原16位深度</a>':''):'';draw()}
async function refresh(){clearTimeout(timer);try{state=await api('/api/live/state');render()}catch(e){$('error').textContent=e.message}finally{timer=setTimeout(refresh,1000)}}
async function action(command){busy=true;render();$('error').textContent='';try{if(command==='start'){await api('/api/live/start',{task_id:$('task').value,seed:Number($('seed').value)})}else{await api('/api/live/control',{run_id:state.run_id,command,command_id:uid()})}}catch(e){$('error').textContent=e.message}finally{busy=false;await refresh()}}
$('start').onclick=()=>action('start');for(const c of ['step','run','pause','stop'])$(c).onclick=()=>action(c);$('refresh').onclick=refresh;$('task').onchange=query;api('/api/live/tasks').then(v=>{tasks=v.tasks;$('task').innerHTML=tasks.map(t=>'<option value="'+esc(t.task_id)+'">'+esc(t.task_id)+' · '+esc(t.query_text)+'</option>').join('');$('seed').innerHTML=v.seeds.map(s=>'<option>'+s+'</option>').join('');query();refresh()}).catch(e=>{$('error').textContent=e.message});
</script></html>'''
